1	/**
2	 * Shared, DEPENDENCY-FREE constants + types for the customer control panel.
3	 *
4	 * This module imports NOTHING (no node builtins, no ssh2, no Prisma) so it is
5	 * safe to import from BOTH client components (the cPanel UI) and server code
6	 * (actions + worker). Anything that touches SSH/secrets lives in lib/ssh-exec.ts
7	 * (server/worker only). Server-action files may only export async functions, so
8	 * every shared const/type the panel needs is parked here.
9	 */
10	
11	// ---- PHP ------------------------------------------------------------------
12	
13	/** PHP-FPM versions the panel can install/select. "" means a static site. */
14	export const PHP_VERSIONS = ["8.3", "8.2", "8.1", "7.4"] as const;
15	export type PhpVersion = (typeof PHP_VERSIONS)[number];
16	
17	// ---- Databases ------------------------------------------------------------
18	
19	export const DB_ENGINES = ["mysql", "postgres"] as const;
20	export type DbEngine = (typeof DB_ENGINES)[number];
21	
22	export const DB_ENGINE_LABEL: Record<DbEngine, string> = {
23	  mysql: "MySQL / MariaDB",
24	  postgres: "PostgreSQL",
25	};
26	
27	// ---- One-click apps -------------------------------------------------------
28	
29	export type AppCatalogItem = {
30	  slug: string;
31	  name: string;
32	  description: string;
33	  /** Engine the app needs provisioned, or null for none. */
34	  engine: DbEngine | null;
35	  /** PHP version the app runs on, or null for a non-PHP app (e.g. Ghost). */
36	  php: PhpVersion | null;
37	  emoji: string;
38	};
39	
40	/** The one-click app catalog. Each reuses the Website + Database primitives. */
41	export const APP_CATALOG: AppCatalogItem[] = [
42	  {
43	    slug: "wordpress",
44	    name: "WordPress",
45	    description: "The world's most popular CMS — blogs, business sites, shops.",
46	    engine: "mysql",
47	    php: "8.3",
48	    emoji: "📝",
49	  },
50	  {
51	    slug: "ghost",
52	    name: "Ghost",
53	    description: "Modern publishing & newsletters (Node.js).",
