3	/**
4	 * Control panel — One-click apps.
5	 *
6	 * Install WordPress / Ghost / Nextcloud / … onto the server: provision a site
7	 * (vhost + docroot) + a database + the app, then report the URL / admin creds.
8	 * This reuses the Website + VpsDatabase primitives — installApp creates all
9	 * three rows (AppInstall, Website, VpsDatabase) and enqueues one APP_INSTALL
10	 * job; worker/apps.ts drives the whole install over SSH (sandbox-simulated on
11	 * staging). Admin + DB passwords are shown once (returned here / on the row).
12	 */
13	import { revalidatePath } from "next/cache";
14	import { db } from "./db";
15	import { requireUser } from "./auth";
16	import { checkRateLimit } from "./rate-limit";
17	import { encryptSecret } from "./crypto-box";
18	import { DOMAIN_RE, generateStrongPassword } from "./ssh-exec";
19	import { appBySlug, type AppRow } from "./cpanel-types";
20	
21	type InstallResult =
22	  | {
23	      ok: true;
24	      id: string;
25	      domain: string;
26	      adminUser: string;
27	      adminPassword: string;
28	      dbName: string;
29	      dbUser: string;
30	      dbPassword: string;
31	    }
32	  | { ok: false; error: string };
33	type Result = { ok: true } | { ok: false; error: string };
34	
35	const EXCLUSIVE_JOBS = [
36	  "PROVISION",
37	  "REINSTALL",
38	  "DELETE",
39	  "RESIZE",
40	  "SUSPEND",
41	  "UNSUSPEND",
42	  "SNAPSHOT_ROLLBACK",
43	  "BACKUP_RESTORE",
44	  // A disk expansion runs growpart/resize2fs over SSH inside the guest; keep the
45	  // control-panel operations out of the way while the root filesystem is resized.
46	  "DISK_EXPAND",
47	] as const;
48	
49	async function ownedServer(serverId: string) {
50	  const user = await requireUser();
51	  const server = await db.server.findUnique({
52	    where: { id: serverId },
53	    select: { id: true, userId: true, status: true, hostname: true },
54	  });
55	  if (!server) throw new Error("Not found");
56	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
57	  return { user, server };
58	}
59	
60	async function ownedApp(id: string) {
61	  const user = await requireUser();
62	  const app = await db.appInstall.findUnique({ where: { id } });
63	  if (!app) throw new Error("Not found");
64	  if (app.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
65	  return { user, app };
66	}
67	
68	function throttle(userId: string, op: string, max: number): string | null {
69	  const rl = checkRateLimit(`cpanel:app:${op}:${userId}`, { max, windowMs: 60_000 });
70	  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
71	}
72	
73	async function lifecycleBusy(serverId: string): Promise<boolean> {
74	  const n = await db.job.count({
75	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: EXCLUSIVE_JOBS as any } },
76	  });
77	  return n > 0;
78	}
79	
80	function safeError(err: unknown): string {
81	  const msg = err instanceof Error ? err.message : String(err);
82	  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
83	  return msg.slice(0, 300);
84	}
85	
86	function rowOut(a: {
87	  id: string;
88	  appSlug: string;
89	  domain: string;
90	  url: string | null;
91	  adminUser: string | null;
92	  status: string;
93	  error: string | null;
94	  createdAt: Date;
95	}): AppRow {
96	  return {
97	    id: a.id,
98	    appSlug: a.appSlug,
99	    domain: a.domain,
100	    url: a.url,
101	    adminUser: a.adminUser,
102	    status: a.status,
103	    error: a.error,
104	    createdAt: a.createdAt.toISOString(),
105	  };
106	}
107	
108	/** Derive a safe DB identifier (letters/digits/underscore, <=32) from a domain. */
109	function dbIdentFromDomain(domain: string, prefix: string): string {
110	  const base = domain.replace(/[^a-z0-9]/gi, "_").slice(0, 20);
111	  const suffix = Math.random().toString(36).slice(2, 6);
112	  return `${prefix}_${base}_${suffix}`.replace(/_+/g, "_").slice(0, 32);
113	}
