170	      `/dashboard/servers/${site.serverId}?tab=control panel`
171	    );
172	  } catch (e: any) {
173	    const reason = String(e?.message ?? e).slice(0, 400);
174	    await db.website.update({ where: { id: site.id }, data: { status: "FAILED", error: reason } });
175	    await notify(site.userId, `Website ${site.domain} failed`, reason.slice(0, 200), `/dashboard/servers/${site.serverId}`);
