import { db } from "../lib/db";
import { randomBytes } from "node:crypto";
import { SANDBOX } from "../lib/sandbox";
import { decryptSecret } from "../lib/crypto-box";
import {
  withServerSsh,
  exec,
  execInput,
  assertDomain,
  assertIdent,
  assertPath,
  assertPhp,
  assertSlug,
  assert,
  shellQuote,
  pkgInstallPrefix,
  SETUP_TIMEOUT_MS,
  INSTALL_TIMEOUT_MS,
  QUICK_TIMEOUT_MS,
} from "../lib/ssh-exec";
import { ensureNginx, ensurePhpFpm, nginxVhost, reloadNginx, sshServer } from "./websites";
import { ensureMysql, ensurePostgres } from "./databases";
import { appBySlug } from "../lib/cpanel-types";
import type { Job } from "@prisma/client";
import type { Client } from "ssh2";

/**
 * Control-panel APP_INSTALL handler (one-click apps).
 *
 * Registered in worker/index.ts:
 *   APP_INSTALL: appInstall,
 *
 * ---------------------------------------------------------------------------
 * THE RULE THIS FILE EXISTS TO ENFORCE: never report an install we did not do.
 *
 * The previous version provisioned a vhost + a database for ghost/nextcloud/
 * joomla/matomo, wrote a "<App> is ready to install" placeholder page, and then
 * marked the row ACTIVE — so the panel showed a green pill and a live link for
 * an install that had not happened. It also generated an "admin password", told
 * the customer it was shown only once, and never created any account with it
 * (`adminPassEnc` was written, then nulled, and never once decrypted).
 *
 * That is the same defect class as the SSL rows written ACTIVE with invented
 * expiries while certbot never ran, and the migration engine logging "Sites
 * actually serving: 4/4" with six domains dark: a code path reporting an
 * outcome it never verified. So every app here now declares HOW MUCH of the
 * install this platform actually performs (`APP_MODES`), and the row only
 * settles to a state we PROVED:
 *
 *   managed  (wordpress) — we download core, write wp-config.php, run the real
 *              installer so the admin account exists, then prove over HTTP that
 *              the site serves WordPress and prove in PHP that the exact
 *              password we showed the customer authenticates that account.
 *              Only then → ACTIVE.
 *   assisted (nextcloud, joomla, matomo) — we prepare the vhost, the database
 *              and the application's REAL files, verify the application's own
 *              setup wizard is being served, and settle the row to NEEDS_SETUP
 *              with exactly what is left and where the files are. Never ACTIVE:
 *              the customer, not us, finishes these installs.
 *   unavailable (ghost) — not offered. It needs its own Node runtime, a systemd
 *              service and a reverse proxy, and its owner account can only be
 *              created in a browser, so "one click" would be a lie. The UI hides
 *              it, lib/actions-apps.ts refuses it, and this handler refuses it
 *              too (a stale queued job must not be able to fake an ACTIVE row).
 *
 * An exit code of 0 is NEVER accepted as proof on its own: `verifyServing()`
 * fetches the site from inside the VM with the Host header pinned and matches
 * application markers in the body. If verification fails the job FAILS with the
 * probe result — we do not downgrade a broken install to "needs setup".
 *
 * SSH hygiene (lib/ssh-exec): every interpolated value is allowlist-validated
 * and quoted; DB/admin passwords only ever travel through a command's STDIN or
 * a 0600 file — never through argv, which is world-readable in /proc.
 *
 * SANDBOX / non-ENABLE_REAL_CPANEL: no SSH, exactly like every other worker
 * feature — but the simulated outcome still follows the app's declared mode
 * (assisted apps settle to NEEDS_SETUP on staging too, so staging never shows a
 * greener result than production would).
 */

const REAL = !SANDBOX && process.env.ENABLE_REAL_CPANEL === "1";

// ---------------------------------------------------------------------------
// What this platform actually does per app (single source of truth).
// lib/actions-apps.ts imports this to decide whether an admin password is even
// generated, and re-exports it to the panel so the catalogue card promises the
// same thing the installer delivers.
// ---------------------------------------------------------------------------

export type AppMode = "managed" | "assisted" | "unavailable";

export type AppModeInfo = {
  mode: AppMode;
  /** Shown on the catalogue card BEFORE the customer commits. */
  promise: string;
  /** What the customer still has to do. "" only for a managed app. */
  remaining: string;
};

export const APP_MODES: Record<string, AppModeInfo> = {
  wordpress: {
    mode: "managed",
    promise: "Installed end to end — your admin login works immediately.",
    remaining: "",
  },
  nextcloud: {
    mode: "assisted",
    promise: "Files, vhost and database prepared — you finish Nextcloud's own setup wizard.",
    remaining:
      "Open the site and complete Nextcloud's setup wizard: it asks for the database name, user and " +
      "password shown when you started the install (database host: localhost) and lets you choose your " +
      "own admin account. Nxeon does not create a Nextcloud account for you.",
  },
  joomla: {
    mode: "assisted",
    promise: "Files, vhost and database prepared — you finish Joomla's own installer.",
    remaining:
      "Open the site to run Joomla's installer: you pick the administrator login, and on the database " +
      "step enter host localhost plus the database name, user and password shown when you started the " +
      "install. Delete the installation/ folder when Joomla offers to.",
  },
  matomo: {
    mode: "assisted",
    promise: "Files, vhost and database prepared — you finish Matomo's own installer.",
    remaining:
      "Open the site and follow Matomo's installer: the database step wants host localhost plus the " +
      "database name, user and password shown when you started the install, and you choose the " +
      "super-user login there.",
  },
  ghost: {
    mode: "unavailable",
    promise: "Not offered as a one-click install.",
    remaining:
      "Ghost needs its own Node.js runtime, a systemd service and a reverse proxy, and its owner " +
      "account can only be created in the browser — so we do not pretend to install it in one click. " +
      "Create a website and a MySQL database in this panel, then install Ghost over SSH with ghost-cli.",
  },
};

export function appMode(slug: string): AppModeInfo {
  return (
    APP_MODES[slug] ?? {
      mode: "unavailable",
      promise: "Not offered as a one-click install.",
      remaining: "This application is not part of the one-click catalogue.",
    }
  );
}

// ---------------------------------------------------------------------------
// Install recipes. Only fixed strings live here — nothing customer-supplied.
// ---------------------------------------------------------------------------

/** One HTTP check that must pass before we describe the install as anything. */
type Probe = {
  /** Path on the app's own domain. */
  path: string;
  /** Every pattern must be present in the body. */
  require: RegExp[];
  /** No pattern may be present (application-level error pages). */
  reject?: RegExp[];
  /** What passing this probe proves — quoted verbatim in failures. */
  proves: string;
};

type Recipe = {
  /**
   * Download candidates, tried in order. Upstream "latest" URLs move around;
   * a single hardcoded URL turns a vendor change into a broken feature, so we
   * try each and then verify the PAYLOAD (see `marker`) rather than trusting
   * that curl exited 0.
   */
  sources: string[];
  archive: "tar.gz" | "zip";
  /** Directory inside the archive whose CONTENTS become the docroot ("" = root). */
  top: string;
  /** File that must exist in the docroot afterwards — proves it is the real app. */
  marker: string;
  /** Extensions the app hard-requires beyond ensurePhpFpm's set. */
  phpExt: string[];
  /** Extra nginx directives merged into the managed vhost (see hardenVhost). */
  nginx: string;
  probes: Probe[];
};

const RECIPES: Record<string, Recipe> = {
  wordpress: {
    sources: ["https://wordpress.org/latest.tar.gz"],
    archive: "tar.gz",
    top: "wordpress",
    marker: "wp-settings.php",
    phpExt: [],
    // An uploaded .php in wp-content/uploads is the classic WordPress takeover:
    // the generic vhost happily hands any *.php to php-fpm. This must be
    // inserted BEFORE that block — nginx uses the FIRST matching regex location.
    nginx:
      `    location ~* ^/wp-content/uploads/.*\\.php$ { deny all; }\n` +
      `    location ~ /\\.(?!well-known) { deny all; }\n`,
    probes: [
      {
        path: "/",
        require: [/wp-content|wp-json|wp-includes/i],
        reject: [/Error establishing a database connection/i],
        proves: "the domain serves WordPress (not a placeholder or the stock nginx page)",
      },
      {
        path: "/wp-login.php",
        require: [/wp-submit/i, /user_login/i],
        reject: [/Error establishing a database connection/i],
        proves: "the login form the customer's credentials are for is reachable",
      },
      {
        // If wp_install() had not really run, this page shows the setup FORM
        // instead — which is precisely the "saved password opens nothing"
        // failure customers hit before. Also proves php-fpm itself (not just
        // our CLI run) can reach the database.
        path: "/wp-admin/install.php",
        require: [/already installed/i],
        reject: [/weblog_title|Welcome to the famous five/i],
        proves: "WordPress is fully installed and will not re-run its setup wizard",
      },
    ],
  },
  nextcloud: {
    sources: ["https://download.nextcloud.com/server/releases/latest.zip"],
    archive: "zip",
    top: "nextcloud",
    marker: "occ",
    // Nextcloud refuses to run without these; installing them here means the
    // customer meets the setup wizard, not a "PHP module not installed" wall.
    phpExt: ["zip", "intl", "bcmath", "gmp"],
    // Nextcloud's default data directory is INSIDE the docroot. With the generic
    // vhost, GET /data/<user>/files/x would hand a stranger the customer's
    // files, so the upstream deny list is not optional. (We also pre-create a
    // data directory outside the docroot and tell the customer to use it.)
    nginx:
      `    location ~ ^/(?:build|tests|config|lib|3rdparty|templates|data)/ { deny all; }\n` +
      `    location ~ ^/(?:\\.|autotest|occ|issue|indie|db_|console) { deny all; }\n` +
      `    client_max_body_size 512M;\n`,
    probes: [
      {
        path: "/",
        require: [/nextcloud/i],
        reject: [/(PHP module|is not installed|not compatible|Fatal error|Internal Server Error)/i],
        proves: "Nextcloud's own setup wizard is being served from the domain",
      },
    ],
  },
  joomla: {
    sources: [
      "https://downloads.joomla.org/cms/joomla5/latest?format=zip",
      "https://downloads.joomla.org/cms/joomla4/latest?format=zip",
    ],
    archive: "zip",
    top: "",
    marker: "installation/index.php",
    phpExt: ["zip", "intl"],
    nginx:
      `    location ~ ^/(?:logs|tmp|cache|administrator/cache)/ { deny all; }\n` +
      `    location ~ /\\.(?!well-known) { deny all; }\n`,
    probes: [
      {
        path: "/",
        require: [/joomla/i],
        reject: [/(Fatal error|Internal Server Error)/i],
        proves: "Joomla's own installer is being served from the domain",
      },
    ],
  },
  matomo: {
    sources: ["https://builds.matomo.org/matomo-latest.zip", "https://builds.matomo.org/matomo.zip"],
    archive: "zip",
    top: "matomo",
    marker: "matomo.php",
    phpExt: ["zip", "intl"],
    nginx:
      `    location ~ ^/(?:config|core|lang|misc|vendor|tmp)/ { deny all; }\n` +
      `    location ~ /\\.(?!well-known) { deny all; }\n`,
    probes: [
      {
        path: "/",
        require: [/matomo/i],
        reject: [/(Fatal error|Internal Server Error)/i],
        proves: "Matomo's own installer is being served from the domain",
      },
    ],
  },
};

/** WordPress cookie/nonce keys — all eight, or cookies are forgeable. */
const WP_SALT_KEYS = [
  "AUTH_KEY",
  "SECURE_AUTH_KEY",
  "LOGGED_IN_KEY",
  "NONCE_KEY",
  "AUTH_SALT",
  "SECURE_AUTH_SALT",
  "LOGGED_IN_SALT",
  "NONCE_SALT",
] as const;

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[cpanel/app] notify failed", e);
  }
}

async function loadApp(job: Job) {
  const p = (job.payload ?? {}) as { appId?: string };
  if (!p.appId) throw new Error("app job: missing appId");
  const app = await db.appInstall.findUnique({ where: { id: p.appId } });
  if (!app) throw new Error(`AppInstall ${p.appId} not found`);
  return app;
}

/** base64url: A-Za-z0-9-_ only, so it is inert inside SQL/PHP string literals. */
function rand(bytes = 48): string {
  return randomBytes(bytes).toString("base64url");
}

/**
 * Escape a value for a PHP single-quoted literal. Used for the customer's email
 * address and generated passwords, which are written into a file via STDIN and
 * never appear in argv. Control characters are refused rather than escaped —
 * this module rejects, it does not sanitize (lib/ssh-exec.ts).
 */
function php(value: string): string {
  // eslint-disable-next-line no-control-regex
  assert(!/[\x00-\x1f\x7f]/.test(value), "Refusing to embed a control character in generated PHP.");
  return `'${value.replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;
}

/**
 * A generated secret is about to be embedded in a SQL or PHP string literal
 * (delivered over STDIN). generateStrongPassword() is alphanumeric by design;
 * assert it, because a stray quote would break out of that literal.
 */
function assertInertSecret(secret: string, what: string): void {
  assert(/^[A-Za-z0-9]{8,128}$/.test(secret), `Unexpected ${what} shape — refusing to use it.`);
}

/** Trim remote output for a customer-facing error message. */
function why(r: { stdout: string; stderr: string }): string {
  return (r.stderr || r.stdout).replace(/\s+/g, " ").trim().slice(0, 200);
}

/**
 * Merge app-specific directives into the shared vhost from worker/websites.ts.
 *
 * Inserted BEFORE `location / {` on purpose: nginx serves the first matching
 * regex location, so a deny rule appended after the generic `location ~ \.php$`
 * block would never fire for a .php URI — the wp-content/uploads shell block
 * would have been decorative. Throws if the shared template changes shape
 * rather than silently emitting an unhardened vhost.
 */
function hardenVhost(vhost: string, rules: string): string {
  if (!rules) return vhost;
  const anchor = "\n    location / {";
  const at = vhost.indexOf(anchor);
  assert(at > 0, "Unexpected nginx template shape — refusing to write an unhardened vhost.");
  return `${vhost.slice(0, at)}\n${rules}${vhost.slice(at)}`;
}

// ---------------------------------------------------------------------------
// Pre-flight: refuse to overwrite anything that already exists
// ---------------------------------------------------------------------------

/**
 * A one-click install writes a vhost with `cat >` and extracts an archive into
 * the docroot. If the customer already has a hand-rolled site on this domain,
 * or files in that directory, doing so destroys their work — so we refuse
 * instead. Same for the database: the old code used CREATE DATABASE IF NOT
 * EXISTS / CREATE USER IF NOT EXISTS, which silently adopted an existing user
 * WITHOUT applying the new password, leaving the customer holding credentials
 * that do not work.
 */
async function assertNothingToOverwrite(
  conn: Client,
  domain: string,
  docRoot: string,
  database: { engine: string; name: string; dbUser: string } | null
): Promise<void> {
  assertDomain(domain);
  assertPath(docRoot);

  const conf = `/etc/nginx/sites-available/${domain}.conf`;
  const vhost = await exec(conn, `test -e ${shellQuote(conf)} && echo yes || echo no`, QUICK_TIMEOUT_MS);
  assert(
    vhost.stdout.trim() !== "yes",
    `An nginx site for ${domain} already exists on this server. Remove it first — the installer will not overwrite it.`
  );

  const files = await exec(
    conn,
    `if [ -d ${shellQuote(docRoot)} ]; then find ${shellQuote(docRoot)} -mindepth 1 -maxdepth 1 -print 2>/dev/null | head -1; fi`,
    QUICK_TIMEOUT_MS
  );
  assert(
    files.stdout.trim() === "",
    `${docRoot} already contains files. Move or remove them first — the installer will not overwrite them.`
  );

  if (!database) return;
  assertIdent(database.name, "database name");
  assertIdent(database.dbUser, "database user");
  if (database.engine === "mysql") {
    const r = await execInput(
      conn,
      "mysql --protocol=socket -uroot -N -B",
      `SELECT COUNT(*) FROM information_schema.schemata WHERE schema_name = '${database.name}';\n` +
        `SELECT COUNT(*) FROM mysql.user WHERE user = '${database.dbUser}';\n`,
      SETUP_TIMEOUT_MS
    );
    if (r.code !== 0) throw new Error(`could not query MySQL: ${why(r)}`);
    const [dbCount, userCount] = r.stdout.trim().split(/\s+/);
    assert(dbCount === "0", `A database named ${database.name} already exists — refusing to reuse it.`);
    assert(userCount === "0", `A MySQL user named ${database.dbUser} already exists — refusing to reuse it.`);
  } else if (database.engine === "postgres") {
    const r = await execInput(
      conn,
      "sudo -u postgres psql -t -A -v ON_ERROR_STOP=1",
      `SELECT count(*) FROM pg_database WHERE datname = '${database.name}';\n` +
        `SELECT count(*) FROM pg_roles WHERE rolname = '${database.dbUser}';\n`,
      SETUP_TIMEOUT_MS
    );
    if (r.code !== 0) throw new Error(`could not query PostgreSQL: ${why(r)}`);
    const [dbCount, userCount] = r.stdout.trim().split(/\s+/);
    assert(dbCount === "0", `A database named ${database.name} already exists — refusing to reuse it.`);
    assert(userCount === "0", `A PostgreSQL role named ${database.dbUser} already exists — refusing to reuse it.`);
  }
}

// ---------------------------------------------------------------------------
// Database
// ---------------------------------------------------------------------------

/**
 * Create the app's database + user with the generated password (STDIN only),
 * then PROVE that credential works by connecting with it. The customer is shown
 * this password once and types it into the app's setup wizard; "the CREATE
 * statement exited 0" is not evidence that it will log in.
 */
async function provisionDb(
  conn: Client,
  engine: string,
  name: string,
  user: string,
  password: string
): Promise<void> {
  assertIdent(name, "database name");
  assertIdent(user, "database user");
  assertInertSecret(password, "database password");

  if (engine === "mysql") {
    // No IF NOT EXISTS: assertNothingToOverwrite has already established that
    // neither exists, so a collision here is a real error and must surface.
    const sql =
      `CREATE DATABASE \`${name}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;\n` +
      `CREATE USER '${user}'@'localhost' IDENTIFIED BY '${password}';\n` +
      `GRANT ALL PRIVILEGES ON \`${name}\`.* TO '${user}'@'localhost';\n` +
      `FLUSH PRIVILEGES;\n`;
    const r = await execInput(conn, "mysql --protocol=socket -uroot", sql, SETUP_TIMEOUT_MS);
    if (r.code !== 0) throw new Error(`database setup failed: ${why(r)}`);

    // Log in AS the customer's user. The password reaches mysql through a 0600
    // defaults file written by the same shell that deletes it — never argv.
    const check = await execInput(
      conn,
      `umask 077; f=$(mktemp) && cat > "$f" && ` +
        `mysql --defaults-extra-file="$f" --protocol=socket -N -B -e 'SELECT 1' ${shellQuote(name)} >/dev/null 2>&1; ` +
        `rc=$?; rm -f "$f"; exit $rc`,
      `[client]\nuser=${user}\npassword=${password}\n`,
      SETUP_TIMEOUT_MS
    );
    if (check.code !== 0)
      throw new Error(
        `the generated database credentials did not work when tested — not handing the customer a password that does not log in.`
      );
  } else if (engine === "postgres") {
    const sql = `CREATE ROLE "${user}" LOGIN PASSWORD '${password}';\nCREATE DATABASE "${name}" OWNER "${user}";\n`;
    const r = await execInput(conn, "sudo -u postgres psql -v ON_ERROR_STOP=1", sql, SETUP_TIMEOUT_MS);
    if (r.code !== 0) throw new Error(`database setup failed: ${why(r)}`);
    // No login test: nothing in the catalogue provisions PostgreSQL, so rather
    // than ship an untested probe we leave the gap visible here.
  } else {
    throw new Error(`Unsupported database engine: ${engine}`);
  }
}

// ---------------------------------------------------------------------------
// Staging the application's real files
// ---------------------------------------------------------------------------

async function ensureUnzip(conn: Client): Promise<void> {
  const have = await exec(conn, "command -v unzip >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
  if (have.stdout.trim() === "yes") return;
  const prefix = await pkgInstallPrefix(conn);
  const r = await exec(conn, `${prefix} unzip`, INSTALL_TIMEOUT_MS);
  if (r.code !== 0) throw new Error(`unzip install failed: ${why(r)}`);
}

async function ensurePhpExtensions(conn: Client, phpVersion: string, exts: string[]): Promise<void> {
  if (!exts.length) return;
  assertPhp(phpVersion);
  for (const e of exts) assert(/^[a-z0-9]{1,16}$/.test(e), `Unsupported PHP extension: ${e}`);
  const pkgs = exts.map((e) => `php${phpVersion}-${e}`).join(" ");
  const prefix = await pkgInstallPrefix(conn);
  const r = await exec(conn, `${prefix} ${pkgs}`, INSTALL_TIMEOUT_MS);
  if (r.code !== 0) throw new Error(`could not install ${pkgs}: ${why(r)}`);
  // Extensions are only visible to php-fpm after a reload of the pool.
  await exec(conn, `systemctl restart php${phpVersion}-fpm`, SETUP_TIMEOUT_MS);
}

/**
 * Download the application and unpack it into the docroot, then verify the
 * payload really is that application. Returns the URL that worked.
 *
 * Everything interpolated is a fixed string from RECIPES (URLs, archive layout)
 * or an allowlisted path; nothing here comes from the customer.
 */
async function stageAppFiles(conn: Client, recipe: Recipe, docRoot: string, appName: string): Promise<string> {
  assertPath(docRoot);
  assert(/^[a-z0-9._-]*$/.test(recipe.top), `Unsupported archive layout: ${recipe.top}`);
  assert(/^[a-z0-9._/-]+$/.test(recipe.marker), `Unsupported payload marker: ${recipe.marker}`);
  if (recipe.archive === "zip") await ensureUnzip(conn);

  const top = recipe.top ? `${recipe.top}/` : "";
  const extract = recipe.archive === "zip" ? `unzip -q "$a" -d "$t/x"` : `tar -xzf "$a" -C "$t/x"`;
  const urls = recipe.sources.map(shellQuote).join(" ");
  const dest = shellQuote(docRoot);

  const r = await exec(
    conn,
    `set -e; t=$(mktemp -d); a="$t/pkg"; mkdir -p "$t/x"; ok=""; ` +
      `for u in ${urls}; do if curl -fsSL --max-time 600 -o "$a" "$u"; then ok="$u"; break; fi; done; ` +
      `if [ -z "$ok" ]; then rm -rf "$t"; echo "NXAPP:NODOWNLOAD" >&2; exit 20; fi; ` +
      `if ! ${extract}; then rm -rf "$t"; echo "NXAPP:BADARCHIVE" >&2; exit 21; fi; ` +
      `if [ ! -e "$t/x/${top}${recipe.marker}" ]; then rm -rf "$t"; echo "NXAPP:BADPAYLOAD" >&2; exit 22; fi; ` +
      `mkdir -p ${dest}; cp -a "$t/x/${top}." ${dest}/; rm -rf "$t"; ` +
      `printf 'NXAPP:FROM %s\\n' "$ok"`,
    INSTALL_TIMEOUT_MS
  );
  const out = `${r.stdout}\n${r.stderr}`;
  if (/NXAPP:NODOWNLOAD/.test(out))
    throw new Error(`could not download ${appName} from any known release URL — nothing was changed on the server.`);
  if (/NXAPP:BADARCHIVE/.test(out)) throw new Error(`the ${appName} download was not a readable archive.`);
  if (/NXAPP:BADPAYLOAD/.test(out))
    throw new Error(`the ${appName} download did not contain ${recipe.marker} — refusing to treat it as ${appName}.`);
  const from = /NXAPP:FROM (\S+)/.exec(r.stdout);
  if (r.code !== 0 || !from) throw new Error(`${appName} download failed: ${why(r)}`);

  // Prove the files landed where nginx will look, rather than trusting cp -a.
  const marker = await exec(
    conn,
    `test -e ${shellQuote(`${docRoot}/${recipe.marker}`)} && echo yes || echo no`,
    QUICK_TIMEOUT_MS
  );
  assert(marker.stdout.trim() === "yes", `${appName} files are missing from ${docRoot} after unpacking.`);
  return from[1];
}

/**
 * Own the tree as the web user and tighten it: 750/640 means nginx + php-fpm can
 * read (and the app can write where it needs to) while other local accounts on
 * the VM cannot read config files holding the database password. A failed chown
 * is fatal — the previous `|| true` produced root-owned trees where WordPress
 * silently could not write uploads.
 */
async function applyOwnership(conn: Client, docRoot: string): Promise<void> {
  assertPath(docRoot);
  const p = shellQuote(docRoot);
  const own = await exec(conn, `chown -R www-data:www-data ${p} 2>/dev/null || chown -R nginx:nginx ${p}`, SETUP_TIMEOUT_MS);
  if (own.code !== 0) throw new Error(`could not set ownership on ${docRoot}: ${why(own)}`);
  await exec(
    conn,
    `find ${p} -type d -exec chmod 750 {} + && find ${p} -type f -exec chmod 640 {} +`,
    INSTALL_TIMEOUT_MS
  );
}

// ---------------------------------------------------------------------------
// WordPress (managed install)
// ---------------------------------------------------------------------------

/**
 * Write wp-config.php and run WordPress's real installer so the admin account
 * the customer was shown actually exists.
 *
 * Two things the old version got wrong and this must not:
 *  - it defined ONE weak AUTH_KEY, so every site shared guessable cookie salts;
 *    all eight keys are now 48 random bytes each.
 *  - it never ran an installer, so the "admin password shown only once" opened
 *    nothing. We call wp_install() and then re-read the user and check the
 *    password against the stored hash before anyone is told it works.
 *
 * The script is written to a 0600 file OUTSIDE the docroot (never web-reachable)
 * by the same shell invocation that runs and deletes it, and carries the admin
 * password in its body — via STDIN, never argv.
 */
async function installWordpress(
  conn: Client,
  domain: string,
  docRoot: string,
  phpVersion: string,
  creds: { name: string; user: string; password: string },
  admin: { user: string; password: string; email: string }
): Promise<void> {
  assertDomain(domain);
  assertPath(docRoot);
  assertPhp(phpVersion);
  assertIdent(creds.name, "database name");
  assertIdent(creds.user, "database user");
  assertIdent(admin.user, "admin user");
  assertInertSecret(creds.password, "database password");
  assertInertSecret(admin.password, "admin password");

  const salts = WP_SALT_KEYS.map((k) => `define('${k}', '${rand()}');`).join("\n");
  const cfg =
    `<?php\n` +
    `/* Generated by the Nxeon control panel — one-click WordPress install. */\n` +
    `define('DB_NAME', '${creds.name}');\n` +
    `define('DB_USER', '${creds.user}');\n` +
    `define('DB_PASSWORD', '${creds.password}');\n` +
    `define('DB_HOST', 'localhost');\n` +
    `define('DB_CHARSET', 'utf8mb4');\n` +
    `define('DB_COLLATE', '');\n` +
    `${salts}\n` +
    `define('WP_DEBUG', false);\n` +
    // Deliberately NOT defining WP_HOME/WP_SITEURL: hardcoding http:// here
    // would grey out Settings → General and strand the customer on http after
    // they enable SSL from this panel. The installer seeds the URL options
    // instead, so WordPress can be moved to https from its own admin.
    `$table_prefix = 'wp_';\n` +
    `if ( ! defined('ABSPATH') ) define('ABSPATH', __DIR__ . '/');\n` +
    `require_once ABSPATH . 'wp-settings.php';\n`;
  const wrote = await execInput(
    conn,
    `umask 037; cat > ${shellQuote(`${docRoot}/wp-config.php`)}`,
    cfg,
    SETUP_TIMEOUT_MS
  );
  if (wrote.code !== 0) throw new Error(`could not write wp-config.php: ${why(wrote)}`);

  const script =
    `<?php\n` +
    `/* Nxeon one-click WordPress finish — run once, then deleted. */\n` +
    `$_SERVER['HTTP_HOST'] = ${php(domain)};\n` +
    `$_SERVER['SERVER_NAME'] = ${php(domain)};\n` +
    `$_SERVER['SERVER_PORT'] = '80';\n` +
    `$_SERVER['REQUEST_URI'] = '/';\n` +
    `$_SERVER['SCRIPT_NAME'] = '/index.php';\n` +
    `$_SERVER['REQUEST_METHOD'] = 'GET';\n` +
    // wp_guess_url() honours WP_SITEURL, so the siteurl/home options are seeded
    // with the real domain instead of a CLI-derived guess.
    `define('WP_SITEURL', ${php(`http://${domain}`)});\n` +
    `define('WP_HOME', ${php(`http://${domain}`)});\n` +
    `define('WP_INSTALLING', true);\n` +
    `require_once ${php(`${docRoot}/wp-load.php`)};\n` +
    `require_once ABSPATH . 'wp-admin/includes/upgrade.php';\n` +
    `if ( is_blog_installed() ) { fwrite(STDERR, "NXWP:ALREADY\\n"); exit(31); }\n` +
    `$res = wp_install(${php(domain)}, ${php(admin.user)}, ${php(admin.email)}, true, '', ${php(admin.password)});\n` +
    `if ( is_wp_error($res) ) { fwrite(STDERR, 'NXWP:ERR ' . $res->get_error_message() . "\\n"); exit(32); }\n` +
    `$uid = ( is_array($res) && isset($res['user_id']) ) ? $res['user_id'] : 0;\n` +
    `if ( is_wp_error($uid) || (int) $uid < 1 ) { fwrite(STDERR, "NXWP:NOUSER\\n"); exit(33); }\n` +
    `$u = get_user_by('login', ${php(admin.user)});\n` +
    `if ( ! $u || (int) $u->ID !== (int) $uid ) { fwrite(STDERR, "NXWP:NOACCOUNT\\n"); exit(34); }\n` +
    // The whole point: prove the password we are about to show authenticates.
    `if ( ! wp_check_password(${php(admin.password)}, $u->user_pass, $u->ID) ) { fwrite(STDERR, "NXWP:BADPASS\\n"); exit(35); }\n` +
    `if ( ! in_array('administrator', (array) $u->roles, true) ) { fwrite(STDERR, "NXWP:NOTADMIN\\n"); exit(36); }\n` +
    `echo "NXWP:OK user=" . (int) $u->ID . "\\n";\n`;

  const run = await execInput(
    conn,
    `umask 077; f=$(mktemp) && cat > "$f" && ` +
      `p=$(command -v php${phpVersion} 2>/dev/null || command -v php 2>/dev/null); ` +
      `if [ -z "$p" ]; then rm -f "$f"; echo "NXWP:NOPHP" >&2; exit 30; fi; ` +
      `"$p" "$f"; rc=$?; rm -f "$f"; exit $rc`,
    script,
    INSTALL_TIMEOUT_MS
  );
  const out = `${run.stdout}\n${run.stderr}`;
  // WordPress's own wp_die() prints its message and exits 0, so a zero exit
  // code proves nothing here — the OK marker is the only accepted evidence.
  if (/NXWP:OK/.test(run.stdout)) return;
  if (/NXWP:NOPHP/.test(out)) throw new Error("no PHP CLI binary on the server — cannot complete the WordPress install.");
  if (/NXWP:ALREADY/.test(out)) throw new Error("this database already contains a WordPress install — refusing to overwrite it.");
  if (/NXWP:BADPASS|NXWP:NOACCOUNT|NXWP:NOUSER/.test(out))
    throw new Error("WordPress ran but the admin account could not be verified — not reporting an install we cannot prove.");
  if (/Error establishing a database connection/i.test(out))
    throw new Error("WordPress could not connect to its database with the generated credentials.");
  throw new Error(`WordPress setup failed: ${why(run)}`);
}

// ---------------------------------------------------------------------------
// Verification — the whole reason this file was rewritten
// ---------------------------------------------------------------------------

/**
 * Fetch one path on the app's own domain FROM INSIDE the VM, with the hostname
 * pinned to 127.0.0.1 (`curl --resolve`). That sends the real Host header, so it
 * genuinely tests "does this vhost serve this application" while remaining
 * correct before the customer's DNS has propagated. Mirrors the probe in
 * worker/migrate-real.ts, which exists because a port check proved only that
 * something was listening while sites returned 502s.
 */
async function httpProbe(conn: Client, domain: string, path: string): Promise<{ code: string; body: string }> {
  assertDomain(domain);
  assert(/^\/[A-Za-z0-9._/-]*$/.test(path), `Unsupported probe path: ${path}`);
  const r = await exec(
    conn,
    `f=$(mktemp); c=$(curl -sS -k -L --max-redirs 5 --max-time 25 ` +
      `--resolve ${shellQuote(`${domain}:80:127.0.0.1`)} --resolve ${shellQuote(`${domain}:443:127.0.0.1`)} ` +
      `-o "$f" -w '%{http_code}' ${shellQuote(`http://${domain}${path}`)} 2>/dev/null); ` +
      `[ -n "$c" ] || c=000; printf 'NXCODE:%s\\n' "$c"; head -c 8192 "$f" 2>/dev/null; rm -f "$f"`,
    SETUP_TIMEOUT_MS
  );
  const out = String(r.stdout ?? "");
  const m = /NXCODE:(\d{3})/.exec(out);
  const nl = out.indexOf("\n");
  // Keep newlines: stripping them would glue words together and make markers
  // unmatchable (see probeBody in worker/migrate-real.ts).
  // eslint-disable-next-line no-control-regex
  const body = (nl < 0 ? "" : out.slice(nl + 1)).replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, " ");
  return { code: m ? m[1] : "000", body };
}

/**
 * Run every probe for the app. Throws with the real HTTP result on the first
 * failure — an install that cannot be proved is a FAILED install, never a
 * quietly-downgraded one. Returns a one-line proof for the audit trail.
 */
async function verifyServing(conn: Client, domain: string, probes: Probe[]): Promise<string> {
  const proof: string[] = [];
  for (const p of probes) {
    const { code, body } = await httpProbe(conn, domain, p.path);
    if (code !== "200")
      throw new Error(`verification failed: ${p.path} returned HTTP ${code}, so ${p.proves} is not true.`);
    for (const re of p.reject ?? []) {
      const hit = re.exec(body);
      if (hit) throw new Error(`verification failed: ${p.path} returned an application error ("${hit[0].slice(0, 80)}").`);
    }
    for (const re of p.require) {
      if (!re.test(body))
        throw new Error(`verification failed: ${p.path} answered 200 but ${p.proves} could not be confirmed.`);
    }
    proof.push(`${p.path}=200`);
  }
  return `verified from the VM (${proof.join(" ")})`;
}

// ---------------------------------------------------------------------------
// Handler
// ---------------------------------------------------------------------------

export async function appInstall(job: Job): Promise<void> {
  const app = await loadApp(job);
  const catalog = appBySlug(app.appSlug);
  const info = appMode(app.appSlug);
  await db.appInstall.update({ where: { id: app.id }, data: { status: "INSTALLING" } });

  try {
    assertSlug(app.appSlug);
    assertDomain(app.domain);
    assert(catalog, `Unknown app: ${app.appSlug}`);
    // A queued job from before this app was withdrawn must not be able to
    // produce an ACTIVE row for an install nobody can perform.
    assert(info.mode !== "unavailable", `${catalog!.name} is not available as a one-click install. ${info.remaining}`);
    const recipe = RECIPES[app.appSlug];
    assert(recipe, `No installer recipe for ${app.appSlug}.`);

    const website = app.websiteId ? await db.website.findUnique({ where: { id: app.websiteId } }) : null;
    const database = app.databaseId ? await db.vpsDatabase.findUnique({ where: { id: app.databaseId } }) : null;
    const docRoot = website?.docRoot ?? `/var/www/${app.domain}`;
    const url = `http://${app.domain}/`;
    assertPath(docRoot);

    // Nextcloud's wizard defaults its data directory to <docroot>/data, which the
    // vhost would then happily serve. Give the customer a path outside the
    // docroot to paste in (and keep the deny rules as a second line of defence).
    const dataDir = `/var/lib/nxeon-apps/${app.domain}/data`;
    const detailParts: string[] = [];

    if (info.mode === "assisted") {
      detailParts.push(`${catalog!.name} files are in ${docRoot}.`);
      if (database) detailParts.push(`Database ${database.name} (user ${database.dbUser}) on localhost is ready.`);
      if (app.appSlug === "nextcloud") detailParts.push(`Use ${dataDir} as the data folder.`);
      detailParts.push(info.remaining);
    }

    let status: "ACTIVE" | "NEEDS_SETUP" = info.mode === "managed" ? "ACTIVE" : "NEEDS_SETUP";
    let detail = detailParts.join(" ");

    if (REAL) {
      const dbPass = database ? decryptSecret(database.passwordEnc) : null;
      const adminPass = decryptSecret(app.adminPassEnc);
      if (database) assert(dbPass, "The generated database password could not be decrypted.");
      if (info.mode === "managed") {
        assert(app.adminUser && adminPass, "The generated admin password could not be decrypted.");
        assert(catalog!.php, `${catalog!.name} needs a PHP version in the catalogue.`);
      }
      const owner = await db.user.findUnique({ where: { id: app.userId }, select: { email: true } });
      const adminEmail =
        owner?.email && /^[^\s@]{1,64}@[A-Za-z0-9.-]{1,190}$/.test(owner.email) ? owner.email : `admin@${app.domain}`;

      const server = await sshServer(app.serverId);
      const proof = await withServerSsh(server, async (conn) => {
        // 0. Nothing of the customer's gets overwritten. Runs before any change.
        await assertNothingToOverwrite(conn, app.domain, docRoot, database);

        // 1. Runtime + site (vhost + docroot), with app-specific hardening.
        await ensureNginx(conn);
        if (catalog!.php) {
          await ensurePhpFpm(conn, catalog!.php);
          await ensurePhpExtensions(conn, catalog!.php, recipe.phpExt);
        }
        await exec(conn, `mkdir -p ${shellQuote(docRoot)}`, SETUP_TIMEOUT_MS);
        const conf = `/etc/nginx/sites-available/${app.domain}.conf`;
        const link = `/etc/nginx/sites-enabled/${app.domain}.conf`;
        await execInput(
          conn,
          `cat > ${shellQuote(conf)}`,
          hardenVhost(nginxVhost(app.domain, docRoot, catalog!.php), recipe.nginx),
          SETUP_TIMEOUT_MS
        );
        await exec(conn, `ln -sf ${shellQuote(conf)} ${shellQuote(link)}`, SETUP_TIMEOUT_MS);

        // 2. Database — created, then proved to accept the generated password.
        if (database && dbPass) {
          if (database.engine === "mysql") await ensureMysql(conn);
          else if (database.engine === "postgres") await ensurePostgres(conn);
          await provisionDb(conn, database.engine, database.name, database.dbUser, dbPass);
        }

        // 3. The application's REAL files (never a placeholder page).
        const from = await stageAppFiles(conn, recipe, docRoot, catalog!.name);

        // 4. Managed apps only: complete first-run setup.
        if (info.mode === "managed" && app.appSlug === "wordpress" && database && dbPass) {
          await installWordpress(
            conn,
            app.domain,
            docRoot,
            catalog!.php!,
            { name: database.name, user: database.dbUser, password: dbPass },
            { user: app.adminUser!, password: adminPass!, email: adminEmail }
          );
        }
        if (app.appSlug === "nextcloud") {
          assertPath(dataDir);
          await exec(
            conn,
            `mkdir -p ${shellQuote(dataDir)} && (chown -R www-data:www-data ${shellQuote(dataDir)} 2>/dev/null || ` +
              `chown -R nginx:nginx ${shellQuote(dataDir)}) && chmod 750 ${shellQuote(dataDir)}`,
            SETUP_TIMEOUT_MS
          );
        }

        // 5. Ownership/permissions, then serve.
        await applyOwnership(conn, docRoot);
        await reloadNginx(conn);

        // 6. VERIFY. Until this returns, nothing is reported to the customer.
        const verified = await verifyServing(conn, app.domain, recipe.probes);
        return `${verified}; files from ${from}`;
      });
      detail = info.mode === "managed" ? proof : `${detail} (${proof})`;
    } else {
      // Sandbox/simulated: say so, and still honour the app's declared mode so
      // staging never shows a greener outcome than production would produce.
      detail = `${detail} Sandbox: no VM was touched.`.trim();
    }

    if (website) await db.website.update({ where: { id: website.id }, data: { status: "ACTIVE", ssl: false, error: null } });
    if (database) await db.vpsDatabase.update({ where: { id: database.id }, data: { status: "ACTIVE", error: null, passwordEnc: null } });
    await db.appInstall.update({
      where: { id: app.id },
      // `error` is the row's status-detail line (the schema has no note column);
      // the panel renders it amber for NEEDS_SETUP, never as a failure.
      data: { status, url, error: detail.slice(0, 900) || null, adminPassEnc: null },
    });

    const href = `/dashboard/servers/${app.serverId}?tab=control panel`;
    if (status === "ACTIVE") {
      await notify(
        app.userId,
        `${catalog!.name} is installed and serving on ${app.domain}`,
        REAL
          ? `Sign in at ${url}wp-login.php with the admin user and password shown at install — the account exists and the login was tested. ${detail}`
          : `${catalog!.name} installed (sandbox — no real VM was touched). URL: ${url}`,
        href
      );
    } else {
      await notify(
        app.userId,
        `${catalog!.name} on ${app.domain} is ready for you to finish setup`,
        `Nxeon prepared the site, the database and ${catalog!.name}'s files, but the install is NOT complete — ` +
          `${catalog!.name} creates its own admin account in its setup wizard. ${detail}`,
        href
      );
    }
  } catch (e: any) {
    const reason = String(e?.message ?? e).slice(0, 400);
    // Never keep secrets on a failed install.
    if (app.databaseId) await db.vpsDatabase.update({ where: { id: app.databaseId }, data: { status: "FAILED", error: reason, passwordEnc: null } }).catch(() => {});
    if (app.websiteId) await db.website.update({ where: { id: app.websiteId }, data: { status: "FAILED", error: reason } }).catch(() => {});
    await db.appInstall.update({ where: { id: app.id }, data: { status: "FAILED", error: reason, adminPassEnc: null } });
    await notify(app.userId, `${catalog?.name ?? "App"} install failed on ${app.domain}`, reason.slice(0, 200), `/dashboard/servers/${app.serverId}`);
  }
}

