"use client";

import { useCallback, useEffect, useMemo, useState, useTransition } from "react";
import { listApps, installApp, removeApp, type AppModeRow } from "@/lib/actions-apps";
import { APP_CATALOG, appBySlug, type AppRow } from "@/lib/cpanel-types";
import { StatusPill, EmptyState, LoadingRows, SecretCard } from "./shared";

/**
 * One-click apps panel.
 *
 * This UI used to promise "the application in one step" for every card and show
 * an "Admin password — save these now" for apps whose install never happened
 * (QA P1-22). It now renders the mode the installer actually implements, which
 * comes from the server (`APP_MODES` in worker/apps.ts) instead of being restated
 * here — so marketing copy and installer behaviour cannot drift apart:
 *
 *   managed     → installed end to end; admin credentials are real and tested.
 *   assisted    → site + database + the app's files are prepared, and the card
 *                 says so BEFORE the customer commits; the row settles to
 *                 "Finish setup", never to a green install.
 *   unavailable → not shown at all.
 */
export function AppsPanel({ serverId, running }: { serverId: string; running: boolean }) {
  const [apps, setApps] = useState<AppRow[] | null>(null);
  const [modes, setModes] = useState<AppModeRow[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [selected, setSelected] = useState<string | null>(null);
  const [domain, setDomain] = useState("");
  const [adminUser, setAdminUser] = useState("admin");
  const [formError, setFormError] = useState<string | null>(null);
  const [secret, setSecret] = useState<{ rows: { label: string; value: string }[]; name: string; note: string } | null>(
    null
  );
  const [pending, start] = useTransition();

  const refresh = useCallback(async () => {
    const res = await listApps(serverId);
    if (res.ok) {
      setApps(res.apps);
      setModes(res.modes);
    } else setError(res.error);
  }, [serverId]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  useEffect(() => {
    if (!apps?.some((a) => ["PENDING", "INSTALLING"].includes(a.status))) return;
    const t = setInterval(() => void refresh(), 5000);
    return () => clearInterval(t);
  }, [apps, refresh]);

  const modeOf = useCallback((slug: string) => modes.find((m) => m.slug === slug), [modes]);

  /**
   * Only the apps this platform can actually deliver. Until `modes` has loaded
   * the grid stays empty rather than offering an app we might have withdrawn —
   * a card that cannot be honoured must never be clickable.
   */
  const offered = useMemo(
    () => APP_CATALOG.filter((a) => modeOf(a.slug) && modeOf(a.slug)!.mode !== "unavailable"),
    [modeOf]
  );

  const install = () =>
    start(async () => {
      if (!selected) return;
      setFormError(null);
      const res = await installApp(serverId, selected, domain, adminUser);
      if (!res.ok) setFormError(res.error);
      else {
        setSecret({ rows: res.credentials, name: res.appName, note: res.note });
        setSelected(null);
        setDomain("");
        await refresh();
      }
    });

  const remove = (a: AppRow) =>
    start(async () => {
      setError(null);
      const res = await removeApp(a.id);
      if (!res.ok) setError(res.error);
      await refresh();
    });

  const selectedMode = selected ? modeOf(selected) : undefined;

  return (
    <div className="space-y-6">
      <div className="card">
        <h3 className="mb-1 font-semibold">One-click apps</h3>
        <p className="mb-4 text-sm text-slate-400">
          Provisions a website (vhost + docroot), a database and the application&apos;s files. Point the
          domain&apos;s DNS at this server first. Apps marked <span className="text-amber-300">you finish setup</span>{" "}
          hand over to the application&apos;s own setup wizard — we tell you exactly what is left. Generated
          passwords are shown once.
        </p>
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
          {offered.map((app) => {
            const active = selected === app.slug;
            const mode = modeOf(app.slug)!;
            return (
              <button
                key={app.slug}
                type="button"
                disabled={!running}
                onClick={() => setSelected(active ? null : app.slug)}
                className={`card-hover flex items-start gap-3 rounded-2xl border p-4 text-left transition-all disabled:opacity-50 ${
                  active ? "border-brand-500/60 bg-brand-500/[0.06]" : "border-white/[0.06] bg-navy-900/60"
                }`}
              >
                <span className="text-2xl">{app.emoji}</span>
                <span>
                  <span className="block text-sm font-semibold text-slate-100">{app.name}</span>
                  <span className="mt-0.5 block text-xs text-slate-400">{app.description}</span>
                  <span
                    className={`mt-1.5 block text-[11px] ${
                      mode.mode === "managed" ? "text-emerald-300" : "text-amber-300"
                    }`}
                  >
                    {mode.mode === "managed" ? "Fully installed" : "You finish setup"} — {mode.promise}
                  </span>
                </span>
              </button>
            );
          })}
        </div>

        {selected && selectedMode && (
          <div className="mt-4 border-t border-white/[0.06] pt-4">
            <div className="flex flex-wrap items-end gap-3">
              <div className="grow">
                <label className="label">Domain</label>
                <input className="input" placeholder="blog.example.com" value={domain} onChange={(e) => setDomain(e.target.value)} disabled={pending} />
              </div>
              {/* An admin user is only asked for when we are the ones creating the
                  account. Assisted apps create it in their own wizard. */}
              {selectedMode.mode === "managed" && (
                <div>
                  <label className="label">Admin user</label>
                  <input className="input w-40" value={adminUser} onChange={(e) => setAdminUser(e.target.value)} disabled={pending} maxLength={32} />
                </div>
              )}
              <button className="btn-primary" onClick={install} disabled={pending || domain.trim().length < 3}>
                {pending ? "Installing…" : `Install ${appBySlug(selected)?.name}`}
              </button>
            </div>
            {selectedMode.mode === "assisted" && (
              <p className="mt-3 max-w-2xl text-xs text-amber-300">
                Heads up: this does not finish the install. {selectedMode.remaining}
              </p>
            )}
          </div>
        )}
        {!running && <p className="mt-2 text-xs text-amber-300">Start the server to install apps.</p>}
        {formError && <p className="mt-2 text-sm text-red-400">{formError}</p>}
        {secret && (
          <>
            <SecretCard title={`${secret.name} — credentials`} rows={secret.rows} onDismiss={() => setSecret(null)} />
            <p className="mt-2 max-w-2xl text-xs text-slate-400">{secret.note}</p>
          </>
        )}
      </div>

      <div className="card p-0">
        <p className="section-label px-4 pt-4">Installed apps</p>
        {error && <p className="px-4 pt-3 text-sm text-red-400">{error}</p>}
        {apps === null ? (
          <LoadingRows />
        ) : apps.length === 0 ? (
          <EmptyState title="No apps installed" hint="Pick an application above to deploy it in one click." />
        ) : (
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>App</th>
                <th>Domain</th>
                <th>Status</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {apps.map((a) => (
                <tr key={a.id}>
                  <td>
                    <span className="mr-1.5">{appBySlug(a.appSlug)?.emoji}</span>
                    <span className="font-medium text-slate-100">{appBySlug(a.appSlug)?.name ?? a.appSlug}</span>
                  </td>
                  <td>
                    {a.url ? (
                      <a href={a.url} target="_blank" rel="noreferrer" className="text-brand-300 hover:underline">
                        {a.domain}
                      </a>
                    ) : (
                      <span className="text-slate-400">{a.domain}</span>
                    )}
                  </td>
                  <td>
                    <StatusPill status={a.status} />
                    {/* The detail line is a failure reason only when the row FAILED.
                        For "Finish setup" it is the instructions — what is left and
                        where the files are — so it is shown in full, not truncated
                        away as if it were noise. */}
                    {a.error && a.status === "FAILED" && (
                      <div className="mt-1 max-w-xs truncate text-[11px] text-red-400" title={a.error}>
                        {a.error}
                      </div>
                    )}
                    {a.error && a.status === "NEEDS_SETUP" && (
                      <div className="mt-1 max-w-md text-[11px] leading-relaxed text-amber-300">{a.error}</div>
                    )}
                    {a.error && a.status !== "FAILED" && a.status !== "NEEDS_SETUP" && (
                      <div className="mt-1 max-w-xs truncate text-[11px] text-slate-400" title={a.error}>
                        {a.error}
                      </div>
                    )}
                  </td>
                  <td>
                    <div className="flex justify-end">
                      <button
                        className="btn-danger px-2.5 py-1 text-xs"
                        disabled={pending || a.status === "INSTALLING"}
                        onClick={() => {
                          if (window.confirm(`Remove ${appBySlug(a.appSlug)?.name ?? a.appSlug} on ${a.domain}? Its site and database are deleted.`))
                            remove(a);
                        }}
                      >
                        Remove
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

