333	/** base64url: A-Za-z0-9-_ only, so it is inert inside SQL/PHP string literals. */
334	function rand(bytes = 48): string {
335	  return randomBytes(bytes).toString("base64url");
336	}
337	
338	/**
339	 * Escape a value for a PHP single-quoted literal. Used for the customer's email
340	 * address and generated passwords, which are written into a file via STDIN and
341	 * never appear in argv. Control characters are refused rather than escaped —
342	 * this module rejects, it does not sanitize (lib/ssh-exec.ts).
343	 */
344	function php(value: string): string {
345	  // eslint-disable-next-line no-control-regex
346	  assert(!/[\x00-\x1f\x7f]/.test(value), "Refusing to embed a control character in generated PHP.");
347	  return `'${value.replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;
348	}
349	
350	/**
351	 * A generated secret is about to be embedded in a SQL or PHP string literal
352	 * (delivered over STDIN). generateStrongPassword() is alphanumeric by design;
353	 * assert it, because a stray quote would break out of that literal.
354	 */
355	function assertInertSecret(secret: string, what: string): void {
356	  assert(/^[A-Za-z0-9]{8,128}$/.test(secret), `Unexpected ${what} shape — refusing to use it.`);
357	}
358	
359	/** Trim remote output for a customer-facing error message. */
360	function why(r: { stdout: string; stderr: string }): string {
361	  return (r.stderr || r.stdout).replace(/\s+/g, " ").trim().slice(0, 200);
362	}
