522	async function ensureUnzip(conn: Client): Promise<void> {
523	  const have = await exec(conn, "command -v unzip >/dev/null 2>&1 && echo yes || echo no", QUICK_TIMEOUT_MS);
524	  if (have.stdout.trim() === "yes") return;
525	  const prefix = await pkgInstallPrefix(conn);
526	  const r = await exec(conn, `${prefix} unzip`, INSTALL_TIMEOUT_MS);
527	  if (r.code !== 0) throw new Error(`unzip install failed: ${why(r)}`);
528	}
