530	async function ensurePhpExtensions(conn: Client, phpVersion: string, exts: string[]): Promise<void> {
531	  if (!exts.length) return;
532	  assertPhp(phpVersion);
533	  for (const e of exts) assert(/^[a-z0-9]{1,16}$/.test(e), `Unsupported PHP extension: ${e}`);
534	  const pkgs = exts.map((e) => `php${phpVersion}-${e}`).join(" ");
535	  const prefix = await pkgInstallPrefix(conn);
536	  const r = await exec(conn, `${prefix} ${pkgs}`, INSTALL_TIMEOUT_MS);
537	  if (r.code !== 0) throw new Error(`could not install ${pkgs}: ${why(r)}`);
538	  // Extensions are only visible to php-fpm after a reload of the pool.
539	  await exec(conn, `systemctl restart php${phpVersion}-fpm`, SETUP_TIMEOUT_MS);
540	}
