590	/**
591	 * Own the tree as the web user and tighten it: 750/640 means nginx + php-fpm can
592	 * read (and the app can write where it needs to) while other local accounts on
593	 * the VM cannot read config files holding the database password. A failed chown
594	 * is fatal — the previous `|| true` produced root-owned trees where WordPress
595	 * silently could not write uploads.
596	 */
597	async function applyOwnership(conn: Client, docRoot: string): Promise<void> {
598	  assertPath(docRoot);
599	  const p = shellQuote(docRoot);
600	  const own = await exec(conn, `chown -R www-data:www-data ${p} 2>/dev/null || chown -R nginx:nginx ${p}`, SETUP_TIMEOUT_MS);
601	  if (own.code !== 0) throw new Error(`could not set ownership on ${docRoot}: ${why(own)}`);
602	  await exec(
603	    conn,
604	    `find ${p} -type d -exec chmod 750 {} + && find ${p} -type f -exec chmod 640 {} +`,
605	    INSTALL_TIMEOUT_MS
606	  );
607	}
