133	// ---------------------------------------------------------------------------
134	
135	/**
136	 * The catalogue's install modes, returned alongside the rows so the panel labels
137	 * every card with what this platform actually does. It travels with `listApps`
138	 * rather than as a shared constant because APP_MODES lives in worker/apps.ts
139	 * (server-only) and a "use server" module may export nothing but async
140	 * functions — the panel must not be able to render a promise we don't keep.
141	 */
142	function modeRows(): AppModeRow[] {
143	  return APP_CATALOG.map((a) => ({ slug: a.slug, ...appMode(a.slug) }));
144	}
145	
146	export async function listApps(
147	  serverId: string
148	): Promise<{ ok: true; apps: AppRow[]; modes: AppModeRow[] } | { ok: false; error: string }> {
149	  try {
150	    const { server } = await ownedServer(serverId);
151	    const rows = await db.appInstall.findMany({
152	      where: { serverId: server.id },
153	      orderBy: { createdAt: "desc" },
154	    });
155	    return { ok: true, apps: rows.map(rowOut), modes: modeRows() };
156	  } catch (err) {
157	    return { ok: false, error: safeError(err) };
158	  }
159	}
160	
161	export async function installApp(
162	  serverId: string,
163	  appSlug: string,
164	  domainInput: string,
165	  adminUserInput?: string
166	): Promise<InstallResult> {
167	  try {
168	    const { user, server } = await ownedServer(serverId);
169	    const limited = throttle(user.id, "install", 6);
170	    if (limited) return { ok: false, error: limited };
171	    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to install an app." };
172	    if (await lifecycleBusy(server.id))
173	      return { ok: false, error: "Another server operation is in progress — try again shortly." };
174	
175	    const app = appBySlug(appSlug);
176	    if (!app) return { ok: false, error: "Unknown application." };
177	
178	    // Apps we cannot install end to end are not sold as one-click installs; say
179	    // so up front instead of queueing a job that would have to lie or fail.
180	    const info = appMode(app.slug);
181	    if (info.mode === "unavailable") return { ok: false, error: `${app.name} — ${info.remaining}` };
182	
183	    const domain = String(domainInput ?? "").toLowerCase().trim().replace(/\.$/, "");
184	    if (!DOMAIN_RE.test(domain))
185	      return { ok: false, error: "Enter a valid domain (e.g. blog.example.com) pointed at this server." };
186	
187	    // Domain must be free of an existing website on this server.
188	    const dupSite = await db.website.findFirst({ where: { serverId: server.id, domain } });
189	    if (dupSite) return { ok: false, error: `A website for ${domain} already exists on this server.` };
190	
191	    // An admin account only exists for apps whose install we complete ourselves.
192	    const managed = info.mode === "managed";
193	    const adminUser = managed
194	      ? (String(adminUserInput ?? "admin").replace(/[^a-z0-9_]/gi, "") || "admin").slice(0, 32)
195	      : null;
196	    const adminPassword = managed ? generateStrongPassword(18) : "";
197	    const dbName = app.engine ? dbIdentFromDomain(domain, "db") : "";
198	    const dbUser = app.engine ? dbIdentFromDomain(domain, "u") : "";
199	    const dbPassword = app.engine ? generateStrongPassword(20) : "";
200	
201	    // Create the primitives + the install record in one transaction.
202	    const { appRow } = await db.$transaction(async (tx) => {
203	      const website = await tx.website.create({
204	        data: {
205	          userId: user.id,
206	          serverId: server.id,
207	          domain,
208	          docRoot: `/var/www/${domain}`,
209	          phpVersion: app.php,
210	          isSubdomain: domain.split(".").length > 2,
211	          appSlug: app.slug,
212	          status: "PENDING",
213	        },
214	      });
215	      let database: { id: string } | null = null;
216	      if (app.engine) {
217	        database = await tx.vpsDatabase.create({
218	          data: {
219	            userId: user.id,
220	            serverId: server.id,
221	            engine: app.engine,
222	            name: dbName,
223	            dbUser,
224	            passwordEnc: encryptSecret(dbPassword),
225	            status: "PENDING",
226	          },
227	        });
228	      }
229	      const appRow = await tx.appInstall.create({
230	        data: {
231	          userId: user.id,
232	          serverId: server.id,
233	          appSlug: app.slug,
234	          domain,
235	          websiteId: website.id,
236	          databaseId: database?.id ?? null,
237	          adminUser,
238	          // Nothing is stored for an assisted app: the customer creates that
239	          // account inside the application's own wizard, so there is no
240	          // password for us to keep, apply — or claim.
241	          adminPassEnc: managed ? encryptSecret(adminPassword) : null,
242	          status: "PENDING",
243	        },
244	      });
245	      return { appRow };
246	    });
247	
248	    await db.job.create({ data: { type: "APP_INSTALL", serverId: server.id, payload: { appId: appRow.id } } });
249	    await db.auditLog.create({
250	      data: { userId: user.id, action: "cpanel.app.install", detail: `${app.slug} → ${domain} on ${server.hostname}` },
251	    });
252	    revalidatePath(`/dashboard/servers/${serverId}`);
253	
254	    // Credentials returned ONCE — and only the ones that actually exist.
255	    const credentials: { label: string; value: string }[] = [{ label: "URL", value: `http://${domain}/` }];
256	    if (managed && adminUser) {
257	      credentials.push({ label: "Admin user", value: adminUser });
258	      credentials.push({ label: "Admin password", value: adminPassword });
259	    }

